module accu (
	input clk, rst_n, valid_in,
	input [7:0] data_in,
	output reg valid_out,
	output reg [9:0] data_out
);
// Add your design below

	reg [3:0] cnt;
	reg [9:0] sum;

	wire finish;
	assign finish = (cnt==4'd4)? 1'b1 : 1'b0;

	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			cnt <= 4'd0;
			sum <= 10'd0;
			data_out <= 10'd0;
			valid_out <= 1'b0;
		end
		else begin
			if(valid_in && !finish) begin
				cnt <= cnt + 1'b1;
				sum <= sum + data_in;
			end
			else if(finish) begin
				cnt <= 4'd0;
				sum <= 10'd0;
				valid_out <= 1'b1;
			end
			else begin
				cnt <= cnt;
				sum <= sum;
				valid_out <= 1'b0;
			end
		end
	end

endmodule
